style:
.tw-cosolar--lanzhou.resume-paper {
  color: #243447;
}

.tw-cosolar--lanzhou.resume-paper .paper-header {
  position: relative;
  display: block;
  margin-bottom: 8mm;
  padding: 0;
  border-bottom: none;
  text-align: center;
}

.tw-cosolar--lanzhou.resume-paper .paper-header::before {
  content: "RESUME";
  position: absolute;
  top: calc(var(--paper-mt, 15mm) * -1);
  left: calc(4mm - var(--paper-ml, 15mm));
  box-sizing: border-box;
  width: 11mm;
  height: 46mm;
  padding-top: 8mm;
  background: var(--paper-accent);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.82);
  font-weight: 700;
  letter-spacing: 0.34em;
  line-height: 11mm;
  text-align: center;
  writing-mode: vertical-rl;
  print-color-adjust: exact;
}

.tw-cosolar--lanzhou.resume-paper .paper-header__main {
  display: block;
}

.tw-cosolar--lanzhou.resume-paper .paper-name-row {
  justify-content: center;
}

.tw-cosolar--lanzhou.resume-paper .paper-name {
  color: #1b3f6f;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.2);
  letter-spacing: 0.18em;
}

.tw-cosolar--lanzhou.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: var(--paper-accent);
}

.tw-cosolar--lanzhou.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #31527c;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-align: center;
}

.tw-cosolar--lanzhou.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #7b8ba1;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-cosolar--lanzhou.resume-paper .paper-photo {
  position: absolute;
  top: -4mm;
  right: 2mm;
  width: 30mm;
  height: 34mm;
  border: 0.7mm solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1.2mm #e7edf5, 0 2mm 5mm -2mm rgba(31, 78, 140, 0.45);
  print-color-adjust: exact;
}

.tw-cosolar--lanzhou.resume-paper .paper-photo--monogram {
  position: absolute;
  top: -4mm;
  right: 2mm;
  display: grid;
  place-items: center;
  background: #eaf0f8;
  color: #1f4e8c;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 1.8);
  font-weight: 700;
}

.tw-cosolar--lanzhou.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 6mm;
  padding: 4mm 46mm 4.2mm 6mm;
  border-radius: 1.5mm;
  background: var(--paper-accent);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.88);
  text-align: left;
  print-color-adjust: exact;
}

.tw-cosolar--lanzhou.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--lanzhou.resume-paper .paper-contact__label {
  color: rgba(255, 255, 255, 0.66);
}

.tw-cosolar--lanzhou.resume-paper .paper-style-block .paper-section__title {
  margin-bottom: 3.4mm;
  padding: 1.6mm 7mm 1.6mm 4mm;
  background: var(--paper-accent);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.06);
  letter-spacing: 0.12em;
  clip-path: polygon(0 0, 100% 0, calc(100% - 4mm) 100%, 0 100%);
  print-color-adjust: exact;
}

.tw-cosolar--lanzhou.resume-paper .paper-item-head:has(> .paper-item-period) {
  display: grid;
  grid-template-columns: 35mm minmax(0, 1fr);
  column-gap: 4mm;
  align-items: baseline;
}

.tw-cosolar--lanzhou.resume-paper .is-job_intention .paper-item-head {
  display: flex;
  align-items: baseline;
  gap: 4mm;
}

.tw-cosolar--lanzhou.resume-paper .is-job_intention .paper-item-period {
  order: 0;
  margin-left: auto;
}

.tw-cosolar--lanzhou.resume-paper .paper-item-period {
  order: -1;
  color: #31527c;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 600;
}

.tw-cosolar--lanzhou.resume-paper .paper-item-title {
  color: #1b3f6f;
  font-size: calc(var(--paper-base-size) * 1.04);
}

.tw-cosolar--lanzhou.resume-paper .paper-item-sub {
  margin-top: 0.8mm;
  color: #5d6d80;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-cosolar--lanzhou.resume-paper .paper-item + .paper-item {
  margin-top: 3.4mm;
}

.tw-cosolar--lanzhou.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  color: #31527c;
  font-weight: 600;
}

.tw-cosolar--lanzhou.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-cosolar--lanzhou.resume-paper .paper-footer {
  border-top: 1px solid #d8e1ee;
  color: #6e7d91;
}
